tool_input.command:
$env:PYTHONIOENCODING='utf-8'
foreach($f in '清单拉取与卖出触发_操作手册.md','数据来源清单.md'){
  Write-Output "=== $f ==="
  Select-String -Path "分析产出\$f" -Pattern 'screen_sh|screen_sz|深市.*标准|11 条|7 条|专用|深市打新|全市场|统一' | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(90,$_.Line.Trim().Length)))"}
}
